/// 按规范标识查找属性定义。
pub fn lookup(id: &str) -> Option<&'static AttrDef> {
    ATTRIBUTES.iter().find(|d| d.id == id)
}

/// 已登记属性数量。
pub fn count() -> usize {
    ATTRIBUTES.len()
}

